def card(work):
    target = 37
    lo, hi, steps, log = (0, 100, 0, [])
    while True:
        guess = (lo + hi) // 2
        steps += 1
        signal = (guess > target) - (guess < target)
        log.append((guess, signal))
        if signal == 0:
            break
        if signal > 0:
            hi = guess - 1
        else:
            lo = guess + 1
    save(work, 'ooda.json', log)
    return [eq('found', log[-1][0], 37), truth('loop converges in <= 7 cycles', steps <= 7, steps)]

